import { chromium } from "@playwright/test";
import fs from "fs";
import * as dotenv from "dotenv";

import connectMongo from "../../config/mongo";
import { USERS } from "./test-users.js";
import Profile from "../../models/Profile";
import Link from "../../models/Link";

dotenv.config();

module.exports = async (config) => {
  // remove test file data
  USERS.forEach((username) => fs.unlinkSync(`./data/${username}.json`));
  fs.unlinkSync(`./data/_test-wcag-user.json`)

  // remove test data in database
  await connectMongo();

  // get IDs with `_tests-*`
  const testUsers = await Profile.find({ username: /_test-/ });
  const testLinks = await Link.find({ username: /_test-/ });

  // delete test documents
  testUsers.map(
    async (user) => await Profile.deleteOne({ username: user.username })
  );
  testLinks.map(
    async (user) => await Link.deleteOne({ username: user.username })
  );
};

export const USERS = [
  "_test-profile-user-1",
  "_test-profile-user-2",
  "_test-profile-user-3",
  "_test-profile-user-4",
];

import { chromium } from "@playwright/test";
import fs from "fs";

const { USERS } = require("./test-users.js");
import icons from '../../config/icons.json';
const links = Object.keys(icons).map((icon, index) => {
  return {
    name: `Link ${index} - ${icon} icon`,
    url: "https://github.com/EddieHubCommunity/LinkFree",
    icon: icon
  }
})

const wcagUser = {
  name: "_TEST-WCAG-USER",
  displayStatsPublic: true,
  type: "personal",
  bio: `Bio for _test-wcag-user`,
  avatar: "https://github.com/eddiejaoude.png",
  links: links
}

const user = (username) => {
  return {
    name: username.toUpperCase(),
    displayStatsPublic: true,
    type: "personal",
    bio: `Bio for ${username}`,
    avatar: "https://github.com/eddiejaoude.png",
    links: [
      {
        name: "Link 1",
        url: "http://eddiejaoude.io",
        icon: "FaBad-Icon",
      },
      {
        name: "Link 2",
        url: "http://eddiehub.org",
        icon: "link",
      },
    ],
  };
};

module.exports = async (config) => {
  USERS.forEach((username) => {
    const data = user(username);

    try {
      fs.writeFileSync(`./data/${username}.json`, JSON.stringify(data));
    } catch (e) {
      console.log(e);
      throw new Error(`Test data "${username}" not created`);
    }
  });

  try {
    fs.writeFileSync(`./data/_test-wcag-user.json`, JSON.stringify(wcagUser));
  } catch (e) {
    console.log(e);
    throw new Error(`Test data "_test-wcag-user" not created`);
  }
};

